import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("ReportServlet");
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String sortCol = req.getParameter("sort");
        String format = req.getParameter("format");

        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Validate reportId is numeric
        if (!reportId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid report id");
            return;
        }

        // Sort column - allow common column names
        if (sortCol == null) {
            sortCol = "created_at";
        }

        // Build query with sort
        String query = "SELECT r.id, r.title, r.body, r.created_at, r.status, u.email " +
                       "FROM reports r JOIN users u ON r.author_id = u.id " +
                       "WHERE r.project_id = " + reportId + " " +
                       "ORDER BY " + sortCol;

        log.info("Executing report query for project: " + reportId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("  {\"id\": %d, \"title\": \"%s\", \"status\": \"%s\", \"email\": \"%s\", \"created\": \"%s\"}",
                    rs.getInt("id"),
                    escapeJson(rs.getString("title")),
                    escapeJson(rs.getString("status")),
                    escapeJson(rs.getString("email")),
                    rs.getTimestamp("created_at").toString());
            }
            out.print("\n]");
            out.flush();
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST creates a new report - uses PreparedStatement (safe)
        String projectId = req.getParameter("project_id");
        String title = req.getParameter("title");
        String body = req.getParameter("body");

        if (projectId == null || title == null || body == null) {
            resp.sendError(400, "Missing fields");
            return;
        }

        String insertSql = "INSERT INTO reports (project_id, title, body, author_id, status, created_at) VALUES (?, ?, ?, ?, 'open', NOW())";
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(insertSql)) {
            ps.setInt(1, Integer.parseInt(projectId));
            ps.setString(2, title);
            ps.setString(3, body);
            ps.setInt(4, getAuthenticatedUserId(req));
            ps.executeUpdate();
            resp.setStatus(201);
        } catch (SQLException | NumberFormatException e) {
            log.warning("Insert failed: " + e.getMessage());
            resp.sendError(500, "Failed to create report");
        }
    }

    private int getAuthenticatedUserId(HttpServletRequest req) {
        // Extracted from session/JWT - not user-controllable
        Object uid = req.getAttribute("authenticated_user_id");
        return uid != null ? (Integer) uid : -1;
    }
}
